"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["98900"],{57596(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.peso_sem_carater_que_pontua","status":422,"titulo":"Peso s\xf3 se aplica a etapa cujo car\xe1ter comp\xf5e a nota final"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.peso_sem_carater_que_pontua","requisitos":[],"oQueAconteceu":["Uma das etapas do pedido de defini\xe7\xe3o de etapas\\n(`PUT .../processos-seletivos/{id}/etapas`) tem car\xe1ter **eliminat\xf3rio** e traz\\n`peso`. O peso s\xf3 entra na f\xf3rmula da nota final das etapas cujo car\xe1ter comp\xf5e a\\nnota (classificat\xf3ria ou ambas); na etapa apenas eliminat\xf3ria, que aprova ou\\nreprova sem pontuar, ele ficaria gravado sem nunca pesar em nada, e quem o\\nconfigurou acreditaria que pesa. A recusa vem em `etapas[n].peso`.","A confer\xeancia \xe9 da primeira passada, que confere a forma de todas as etapas do\\npedido antes de consultar o cat\xe1logo de tipos de etapa, e acumula as viola\xe7\xf5es de\\ntodas as etapas no array `errors[]`\\n(ver [`nome_obrigatorio`](/erros/uniplus.selecao.etapa_processo.nome_obrigatorio)). Um\\npeso menor ou igual a zero \xe9 recusado antes, como\\n[`peso_invalido`](/erros/uniplus.selecao.etapa_processo.peso_invalido), e as duas\\nrecusas n\xe3o aparecem juntas para a mesma etapa."],"comoResolver":["Retire o `peso` da etapa eliminat\xf3ria. Se a etapa deve compor a nota final,\\nmude o car\xe1ter para classificat\xf3ria ou ambas e mantenha o peso. Se a resposta\\ntrouxer outras viola\xe7\xf5es em `errors[]`, corrija todas antes de reenviar."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);